import { DatabaseSync } from 'node:sqlite'
import fs from 'node:fs'
import path from 'node:path'

const dbDir = '/home/user/tanstack-auth/data'
const dbPath = path.join(dbDir, 'app.db')

// Ensure directory exists
if (!fs.existsSync(dbDir)) {
  fs.mkdirSync(dbDir, { recursive: true })
}

const db = new DatabaseSync(dbPath)

// Initialize schema
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL
  );
`)

db.exec(`
  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    expires_at INTEGER NOT NULL,
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
  );
`)

export { db }

import crypto from 'node:crypto'
import { db } from './db'

export function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16).toString('hex')
  const hash = crypto.pbkdf2Sync(password, salt, 1000, 64, 'sha512').toString('hex')
  return `${salt}:${hash}`
}

export function verifyPassword(password: string, stored: string): boolean {
  const parts = stored.split(':')
  if (parts.length !== 2) return false
  const [salt, hash] = parts
  const testHash = crypto.pbkdf2Sync(password, salt, 1000, 64, 'sha512').toString('hex')
  return testHash === hash
}

export function createSession(userId: number): string {
  const token = crypto.randomBytes(32).toString('hex')
  const expiresAt = Date.now() + 1000 * 60 * 60 * 24 * 7 // 7 days
  const stmt = db.prepare('INSERT INTO sessions (id, user_id, expires_at) VALUES (?, ?, ?)')
  stmt.run(token, userId, expiresAt)
  return token
}

export function getSessionUser(token: string): { id: number; username: string } | null {
  const stmt = db.prepare(`
    SELECT s.id as session_id, s.expires_at, u.id as user_id, u.username
    FROM sessions s
    JOIN users u ON s.user_id = u.id
    WHERE s.id = ?
  `)
  const row = stmt.get(token) as any
  if (!row) return null

  if (Date.now() > row.expires_at) {
    // Session expired, delete it
    const deleteStmt = db.prepare('DELETE FROM sessions WHERE id = ?')
    deleteStmt.run(token)
    return null
  }

  return { id: row.user_id, username: row.username }
}

export function deleteSession(token: string): void {
  const stmt = db.prepare('DELETE FROM sessions WHERE id = ?')
  stmt.run(token)
}

import { createServerFn } from '@tanstack/react-start'
import { getCookie, setCookie, deleteCookie } from '@tanstack/react-start/server'
import { db } from './db'
import {
  hashPassword,
  verifyPassword,
  createSession,
  getSessionUser,
  deleteSession
} from './auth-utils'

const SESSION_COOKIE_NAME = 'session_id'

// Server function to get the current authenticated user
export const getCurrentUser = createServerFn({ method: 'GET' })
  .handler(async () => {
    const token = getCookie(SESSION_COOKIE_NAME)
    if (!token) return null
    return getSessionUser(token)
  })

// Server function to login
export const loginUser = createServerFn({ method: 'POST' })
  .validator((data: any) => {
    if (typeof data?.username !== 'string' || typeof data?.password !== 'string') {
      throw new Error('Invalid input')
    }
    return data as { username: string; password: string }
  })
  .handler(async ({ data }) => {
    const { username, password } = data
    if (!username || !password) {
      return { success: false, error: 'Username and password are required' }
    }

    const stmt = db.prepare('SELECT * FROM users WHERE username = ?')
    const user = stmt.get(username) as any
    if (!user) {
      return { success: false, error: 'Invalid username or password' }
    }

    const isMatch = verifyPassword(password, user.password_hash)
    if (!isMatch) {
      return { success: false, error: 'Invalid username or password' }
    }

    const token = createSession(user.id)
    setCookie(SESSION_COOKIE_NAME, token, {
      httpOnly: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 60 * 60 * 24 * 7 // 7 days
    })

    return { success: true }
  })

// Server function to register
export const registerUser = createServerFn({ method: 'POST' })
  .validator((data: any) => {
    if (typeof data?.username !== 'string' || typeof data?.password !== 'string') {
      throw new Error('Invalid input')
    }
    return data as { username: string; password: string }
  })
  .handler(async ({ data }) => {
    const { username, password } = data
    if (!username || !password) {
      return { success: false, error: 'Username and password are required' }
    }

    if (username.length < 3) {
      return { success: false, error: 'Username must be at least 3 characters long' }
    }
    if (password.length < 6) {
      return { success: false, error: 'Password must be at least 6 characters long' }
    }

    // Check if username already exists
    const checkStmt = db.prepare('SELECT id FROM users WHERE username = ?')
    const existing = checkStmt.get(username)
    if (existing) {
      return { success: false, error: 'Username is already taken' }
    }

    // Create user
    const password_hash = hashPassword(password)
    const insertStmt = db.prepare('INSERT INTO users (username, password_hash) VALUES (?, ?)')
    const res = insertStmt.run(username, password_hash) as any

    const token = createSession(res.lastInsertRowid)
    setCookie(SESSION_COOKIE_NAME, token, {
      httpOnly: true,
      sameSite: 'lax',
      path: '/',
      maxAge: 60 * 60 * 24 * 7 // 7 days
    })

    return { success: true }
  })

// Server function to logout
export const logoutUser = createServerFn({ method: 'POST' })
  .handler(async () => {
    const token = getCookie(SESSION_COOKIE_NAME)
    if (token) {
      deleteSession(token)
    }
    deleteCookie(SESSION_COOKIE_NAME, { path: '/' })
    return { success: true }
  })

