import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const clientDir = path.resolve(__dirname, '../../dist/client')
const serverEntryPath = path.resolve(__dirname, '../../dist/server/server.js')

// Import the TanStack Start request handler dynamically
const serverModule = await import(serverEntryPath)
const { fetch: handleStartRequest } = serverModule.default

const PORT = process.env.PORT || 8791

const server = http.createServer(async (req, res) => {
  try {
    const host = req.headers.host || `localhost:${PORT}`
    const url = new URL(req.url || '', `http://${host}`)
    const pathname = url.pathname

    // 1. Serve static files from dist/client if they exist
    const localFilePath = path.join(clientDir, pathname)
    if (fs.existsSync(localFilePath) && fs.statSync(localFilePath).isFile()) {
      const ext = path.extname(localFilePath).toLowerCase()
      const mimeTypes = {
        '.js': 'application/javascript',
        '.css': 'text/css',
        '.ico': 'image/x-icon',
        '.png': 'image/png',
        '.jpg': 'image/jpeg',
        '.jpeg': 'image/jpeg',
        '.svg': 'image/svg+xml',
        '.json': 'application/json',
      }
      const contentType = mimeTypes[ext] || 'application/octet-stream'
      res.writeHead(200, { 'Content-Type': contentType })
      fs.createReadStream(localFilePath).pipe(res)
      return
    }

    // 2. Otherwise, convert to Web Request and let TanStack Start handle it
    const webRequest = await toWebRequest(req, host)
    const webResponse = await handleStartRequest(webRequest)

    await sendWebResponse(webResponse, res)
  } catch (error) {
    console.error('Error handling request:', error)
    if (!res.headersSent) {
      res.writeHead(500, { 'Content-Type': 'text/plain' })
      res.end('Internal Server Error')
    }
  }
})

// Helper to convert Node request to Web Request
async function toWebRequest(req, host) {
  const url = new URL(req.url || '', `http://${host}`)
  const headers = new Headers()
  for (const [key, value] of Object.entries(req.headers)) {
    if (Array.isArray(value)) {
      for (const val of value) {
        headers.append(key, val)
      }
    } else if (value !== undefined) {
      headers.set(key, value)
    }
  }

  const method = req.method || 'GET'
  const init = {
    method,
    headers,
  }

  if (method !== 'GET' && method !== 'HEAD') {
    const chunks = []
    for await (const chunk of req) {
      chunks.push(chunk)
    }
    init.body = Buffer.concat(chunks)
  }

  return new Request(url.href, init)
}

// Helper to write Web Response back to Node ServerResponse
async function sendWebResponse(webRes, res) {
  res.statusCode = webRes.status
  res.statusMessage = webRes.statusText

  for (const [key, value] of webRes.headers.entries()) {
    if (key.toLowerCase() === 'set-cookie') {
      const cookies = webRes.headers.getSetCookie()
      res.setHeader('Set-Cookie', cookies)
    } else {
      res.setHeader(key, value)
    }
  }

  if (webRes.body) {
    const reader = webRes.body.getReader()
    while (true) {
      const { done, value } = await reader.read()
      if (done) break
      res.write(value)
    }
  }
  res.end()
}

server.listen(PORT, () => {
  console.log(`Server listening on http://localhost:${PORT}`)
})
